package com.dy.artisan3d.data.remote.pagingimport androidx.paging.PagingSourceimport androidx.paging.PagingStateimport com.dy.artisan3d.data.model.ProductListResponseimport com.dy.artisan3d.domain.model.NetworkErrorimport com.dy.artisan3d.domain.model.Productimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.Constants.FILE_URLimport io.github.aakira.napier.Napierimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getimport io.ktor.client.request.parameterimport kotlinx.io.IOExceptionimport kotlinx.serialization.SerializationExceptionclass ProductPagingSource(    private val httpClient: HttpClient,    private val lang: String,    private val categoryId: Int? = null, // null bo'lsa barchasi olinadi    private val brandId: Int? = null) : PagingSource<Int, Product>() {    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, Product> {        val page = params.key ?: 1        return try {            val response: ProductListResponse = httpClient.get(BASE_URL+"products") {                parameter("page", page)                // Agar categoryId 0 dan katta bo'lsa queary ga qo'shadi                if (categoryId != null && categoryId > 0) {                    parameter("category_id", categoryId)                }                // Agar brandId 0 dan katta bo'lsa queary ga qo'shadi                if (brandId != null && brandId > 0) {                    parameter("brand_id", brandId)                }            }.body()            // DEBUG: Response'ni tekshiring            Napier.d(tag = "ARTISAN_DEBUG") { "Response keldi: ${response.data.size} ta element" }            Napier.d(tag = "ARTISAN_DEBUG") { "Raw response: $response" }            val products = response.data.map { dto ->                Napier.d(tag = "ARTISAN_DEBUG") { "DTO: id=${dto.id}, slug=${dto.slug}" }                Napier.d(tag = "ARTISAN_DEBUG") { "Mavjud tillar: ${dto.translations.keys}" }                Napier.d(tag = "ARTISAN_DEBUG") { "Siz so'ragan til: $lang" }                val translation = dto.translations[lang]                    ?: dto.translations["uz"]                    ?: dto.translations.values.firstOrNull()                Napier.d(tag = "ARTISAN_DEBUG") { "Translation topildi: ${translation?.name}" }                Product(                    id = dto.id,                    name = translation?.name ?: "Nomsiz (Slug: ${dto.slug})",                    description = translation?.description ?: "Tavsif mavjud emas",                    imageUrl = FILE_URL + dto.images.main,                    glbUrl = dto.images.glb?.let { FILE_URL+it }                )            }            Napier.d(tag = "ARTISAN_DEBUG") { "Mappingdan keyin: ${products.size} ta element" }            val meta = response.meta            LoadResult.Page(                data = products,                // Oldingi sahifa mantiqi: agar hozirgi sahifa 1 bo'lsa, null qaytaramiz.                // Shunda kutubxona manfiyga qarab ketmaydi.                prevKey = if (page <= 1) null else page - 1,                // Keyingi sahifa mantiqi: agar hozirgi sahifa oxirgisi bo'lsa, null qaytaramiz.                nextKey = if (page >= meta.last_page) null else page + 1            )        } catch (e: Exception) {            Napier.e(tag = "ARTISAN_DEBUG") { "XATO: ${e.message}" }            e.printStackTrace()            LoadResult.Error(handleError(e))        }    }    override fun getRefreshKey(state: PagingState<Int, Product>): Int? {        // Bu yerda null qaytarish - refresh bo'lganda har doim        // initialKey (ya'ni 1-sahifa)dan boshlashni anglatadi.        return null    }    private fun handleError(e: Exception): NetworkError {        return when (e) {            is IOException -> NetworkError.NoInternet            is SerializationException -> NetworkError.SerializationError            else -> NetworkError.ServerError        }    }}